head.b:skin:
/* 
THEME: Arabic Curriculum Master (Desert Oasis)
SYSTEM: National Arabic Pedagogy & Exam Framework
*/
:root {
    --olive-dark: #365314;
    --olive-light: #65a30d;
    --sand-bg: #fefce8;
    --gold-border: #ca8a04;
    --paper-white: #ffffff;
}
body {
    background-color: var(--sand-bg);
    color: #1a2e05;
    font-family: 'Inter', 'Traditional Arabic', serif;
    margin: 0; padding: 0;
    background-image: radial-gradient(#eab308 0.5px, transparent 0.5px);
    background-size: 40px 40px;
}
.header-wrap {
    background: var(--olive-dark);
    color: #fef9c3;
    padding: 50px 20px;
    text-align: center;
    border-bottom: 5px solid var(--gold-border);
}
.header-wrap h1 { font-weight: 900; letter-spacing: 2px; margin: 0; font-size: 28px; }
.main-container {
    max-width: 950px;
    margin: -30px auto 60px;
    padding: 20px;
}
.arabic-card {
    background: var(--paper-white);
    border-radius: 15px;
    padding: 40px;
    border: 1px solid #e5e7eb;
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
}
.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: 800;
    margin-bottom: 8px;
    color: var(--olive-dark);
    font-size: 11px;
    text-transform: uppercase;
    border-right: 4px solid var(--gold-border);
    padding-right: 10px;
    text-align: right;
}
.input-group input, .input-group textarea, .input-group select {
    width: 100%;
    padding: 12px;
    border: 2px solid #f1f5f9;
    border-radius: 8px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fff;
    font-size: 15px;
    color: #000;
    transition: 0.3s;
}
.input-group select { border-left: 6px solid var(--olive-light); cursor: pointer; }
.input-group input:focus { border-color: var(--gold-border); outline: none; }

.flex-row { display: flex; gap: 15px; flex-wrap: wrap; }
.flex-item { flex: 1; min-width: 200px; }

h2 { font-weight: 800; font-size: 20px; color: var(--olive-dark); text-align: center; margin-bottom: 30px; }

.copy-btn {
    background: var(--olive-dark);
    color: #fff;
    border: none;
    padding: 20px;
    cursor: pointer;
    font-weight: 800;
    width: 100%;
    border-radius: 8px;
    transition: 0.3s;
    font-size: 16px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.copy-btn:hover { background: var(--olive-light); transform: translateY(-2px); }
footer { text-align: center; color: var(--olive-dark); padding: 40px; font-size: 12px; font-weight: bold; }

body.script:
function copyPrompt() {
    var topic = document.getElementById("inputTopic").value || "Ad-Darsul Awwal";
    var notes = document.getElementById("inputNotes").value || "Fokus pada pemahaman konteks.";
    var level = document.getElementById("inputLevel").value;
    var format = document.getElementById("inputFormat").value;

    var template = document.getElementById("templateID").innerText;

    var finalPrompt = template
        .replace("[USER_TOPIC]", topic)
        .replace("[USER_NOTES]", notes)
        .replace(/\[USER_LEVEL\]/g, level)
        .replace(/\[USER_FORMAT\]/g, format);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("🕌 Arabic Prompt Copied! [Level: " + level.split('(')[0] + "]");
}
